+function building(x,z,title,accent){box(x,1.55,z,8,3.1,6,mat('#394542'));box(x,3.18,z,8.35,.18,6.35,mats.dark);box(x,3.3,z,8.2,.12,6.2,mat(accent,.4,.35));for(let i=-1;i<=1;i++){box(x+i*2.35,1.8,z-3.04,1.7,1.45,.08,mats.glass);box(x+i*2.35,1.8,z-3.1,.08,1.65,.1,mats.metal);box(x+i*2.35,1.8,z-3.1,1.8,.08,.1,mats.metal)}box(x, .78,z-3.08,1.2,1.55,.18,mat('#252e2b'));box(x,3.45,z-3.15,8.4,.3,.25,mat(accent));label(title,x,4.35,z-3.3,accent);for(let i=-1;i<=1;i++)box(x+i*3,3.65,z+3.12,.12,.7,.12,mats.yellow);cylinder(x+3.15,.4,z-3.6,.24,.24,.6,mats.yellow);return {x,z}}
