+const layers=[{name:'Grass & Dirt',at:0,hard:1,color:'#756344',value:18,resource:'Copper'},{name:'Soft Rock',at:70,hard:1.2,color:'#8b7453',value:25,resource:'Quartz'},{name:'Stone Layer',at:210,hard:1.6,color:'#68726d',value:38,resource:'Stone'},{name:'Coal Seam',at:500,hard:2,color:'#414846',value:55,resource:'Coal'},{name:'Iron Vein',at:950,hard:2.5,color:'#785f4a',value:90,resource:'Iron'},{name:'Gold Deposit',at:1600,hard:3.1,color:'#9e792f',value:160,resource:'Gold'},{name:'Diamond Shelf',at:2500,hard:3.8,color:'#4b8583',value:260,resource:'Diamond'},{name:'Volcanic Rock',at:3600,hard:4.7,color:'#612e27',value:340,resource:'Obsidian'},{name:'Magma Zone',at:4700,hard:5.5,color:'#9d3921',value:480,resource:'Magma glass'},{name:'Earth’s Core',at:5700,hard:6.5,color:'#b97c26',value:720,resource:'Core crystal'}];
+let caveGroup=null,targetGroup=null, targetHp=1, targetMax=1,particles=[];
+const ui=id=>document.getElementById(id);function layerNow(){let l=layers[0];for(const x of layers)if(state.depth>=x.at)l=x;return l}function fmt(n){return Math.floor(n).toLocaleString('en-US')}
+function updateUI(){let l=layerNow();ui('money').innerHTML='$<span>'+fmt(state.money)+'</span>';ui('oil').innerHTML=fmt(state.oil)+'<small> / '+state.oilMax+' L</small>';ui('durability').innerHTML=fmt(state.dur)+'<small> %</small>';ui('depth').textContent=fmt(state.depth)+'m';ui('depthFill').style.width=Math.max(1,state.depth/6371*100)+'%';ui('layer').textContent=(state.mode==='surface'?'SURFACE · ':l.name.toUpperCase()+' · ')+String(Math.floor(state.depth)).padStart(3,'0')+' M';ui('depthLayer').textContent=l.name.toUpperCase();ui('objective').textContent=state.depth===0?'Break through the surface crust. Find your first vein.':state.depth>=6371?'Core reached. Continue exploring.':'Descend through '+(layers[layers.indexOf(l)+1]?.name||'the core')+'.';ui('objectiveFill').style.width=Math.min(state.depth/6371*100,100)+'%';ui('surfaceButton').innerHTML=state.mode==='surface'?'<em>↓</em> DESCEND INTO SHAFT':'<em>↑</em> RETURN TO SURFACE'}
+function toast(t){ui('toast').textContent=t;ui('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>ui('toast').classList.remove('show'),2100)}
