ui('objectiveFill').style.width=Math.min(state.depth/6371*100,100)+'%'}
// A dedicated mining meter appears only while underground.
const miningHud=document.createElement('div');miningHud.style.cssText='position:absolute;left:50%;top:calc(50% + 24px);transform:translateX(-50%);width:170px;opacity:0;text-align:center;transition:opacity .2s';miningHud.innerHTML='<div style="font:9px DM Mono;color:#dce7d7;letter-spacing:.12em;margin-bottom:6px">ROCK INTEGRITY</div><div style="height:3px;background:#ffffff33"><i style="display:block;width:100%;height:100%;background:#c8f36a;transition:width .15s"></i></div>';ui('ui').appendChild(miningHud);const miningBar=miningHud.querySelector('i');
function makeCave(){if(caveGroup)scene.remove(caveGroup);caveGroup=new THREE.Group();scene.add(caveGroup);let l=layerNow(),wallMat=new THREE.MeshStandardMaterial({color:l.color,roughness:.92});
// excavated chamber and narrowing bore behind the work face
box(0,-.55,-4,12,1,30,wallMat,caveGroup);box(-5.4,2,-4,1,6,30,wallMat,caveGroup);box(5.4,2,-4,1,6,30,wallMat,caveGroup);box(0,5,-4,12,1,30,wallMat,caveGroup);box(0,2,10,12,6,1,wallMat,caveGroup);
for(let z=-15;z<8;z+=3){let rib=torus(0,2,z,4.7,.12,mat('#555c53'),caveGroup);rib.rotation.y=Math.PI/2;rib.scale.set(1,1.22,1);box(-4.65,2,z,.2,4.3,.24,mats.metal,caveGroup);box(4.65,2,z,.2,4.3,.24,mats.metal,caveGroup)}
// rails, cable and work lights
for(let x of [-1.6,1.6]){box(x,-.02,0,.08,.08,18,mats.metal,caveGroup);for(let z=-12;z<8;z+=2)box(x,.05,z,.12,.15,.2,mats.yellow,caveGroup)}
let cable=cylinder(0,3,-4,.035,.035,26,mats.yellow,caveGroup,8);for(let z of [-11,-4,3]){let lamp=new THREE.PointLight('#ffd18c',2.4,10);lamp.position.set(0,4.2,z);caveGroup.add(lamp);let bulb=new THREE.Mesh(new THREE.SphereGeometry(.12,12,8),new THREE.MeshBasicMaterial({color:'#f9ce79'}));bulb.position.copy(lamp.position);caveGroup.add(bulb)}
// mineral flecks in the walls
let crystalMat=layerNow().name==='Diamond Shelf'?mats.diamond:(layerNow().name==='Gold Deposit'?mats.gold:mats.yellow);for(let i=0;i<22;i++){let side=i%2? -1:1,z=-14+Math.random()*22,y=.4+Math.random()*3.5;let c=new THREE.Mesh(new THREE.OctahedronGeometry(.12+Math.random()*.17),crystalMat);c.position.set(side*(4.85+Math.random()*.08),y,z);c.rotation.set(Math.random(),Math.random(),Math.random());caveGroup.add(c)}
// fresh ore face, fractured strata, and warning beacon
for(let i=0;i<5;i++){let b=box((Math.random()-.5)*3,.45+Math.random()*2,-8,1+Math.random()*1.3,1+Math.random(),.45,wallMat,caveGroup);b.rotation.z=(Math.random()-.5)*.4}
targetGroup=new THREE.Group();caveGroup.add(targetGroup);let main=new THREE.Mesh(new THREE.IcosahedronGeometry(1.5,1),wallMat);main.position.set(0,1.65,-7.3);main.scale.set(1.5,1.3,.65);main.castShadow=true;main.userData.main=true;targetGroup.add(main);
for(let i=0;i<7;i++){let c=new THREE.Mesh(new THREE.OctahedronGeometry(.18+Math.random()*.18),crystalMat);c.position.set((Math.random()-.5)*2.5,1+Math.random()*1.7,-7.3+Math.random()*.5);c.rotation.set(Math.random(),Math.random(),Math.random());targetGroup.add(c)}
targetHp=targetMax=l.hard*(3+Math.floor(state.depth/1400));targetGroup.scale.setScalar(1);miningBar.style.width='100%';camera.position.set(0,1.72,6);camera.rotation.set(0,0,0);state.yaw=0;state.pitch=0;camera.lookAt(0,1.4,-7);state.yaw=0;state.pitch=-.015;}
function setMode(mode){state.mode=mode;if(mode==='cave'){scene.background=new THREE.Color('#101916');scene.fog=new THREE.FogExp2('#121b17',.032);sun.intensity=.12;makeCave();miningHud.style.opacity=1;toast('Lowering into the shaft — keep your drill fed.')}else{scene.background=new THREE.Color('#a5b2a3');scene.fog=new THREE.FogExp2('#9eab9a',.012);sun.intensity=3.3;camera.position.set(0,1.72,12);camera.rotation.set(0,0,0);camera.lookAt(0,1,0);miningHud.style.opacity=0;ui('modalWrap').classList.remove('open');if(caveGroup){scene.remove(caveGroup);caveGroup=null}toast('Surface camp · service your equipment before the next descent.')}updateUI()}
function burst(){if(!targetGroup)return;for(let i=0;i<12;i++){let p=new THREE.Mesh(new THREE.TetrahedronGeometry(.08+Math.random()*.12),mat(layerNow().color));p.position.set((Math.random()-.5)*1.5,1.7+Math.random()*1.2,-7.2);p.userData.v=new THREE.Vector3((Math.random()-.5)*.12,Math.random()*.14,(Math.random()-.5)*.1);caveGroup.add(p);particles.push({mesh:p,life:.8+Math.random()*.5})}}
function mine(){if(state.mode!=='cave'||Date.now()-state.lastMine<250)return;state.lastMine=Date.now();if(state.oil<=0){toast('OUT OF OIL — return to the depot for a refill.');return}if(state.dur<=0){toast('DRILL OVERHEATED — repair it at the science lab.');return}let l=layerNow(),power=1+state.up.power*.38;state.oil=Math.max(0,state.oil-(.35*(1-state.up.eff*.13)));state.dur=Math.max(0,state.dur-(.23+Math.max(0,state.depth-1800)/15000)*(1-state.up.heat*.1));let damage=(1+state.up.speed*.16)*power/Math.max(.7,l.hard);targetHp-=damage;let meters=(11+state.up.speed*2)*power/Math.max(1,l.hard*.65);if(state.depth+meters>=6371){meters=6371-state.depth}state.depth+=meters;targetGroup.scale.setScalar(Math.max(.12,.45+.55*targetHp/targetMax));miningBar.style.width=Math.max(0,targetHp/targetMax*100)+'%';burst();if(targetHp<=0){let capacity=25+state.up.store*20;if(state.inventory<capacity){let payout=Math.floor(l.value*(.72+Math.random()*.56));state.money+=payout;state.inventory++;toast(l.resource+' recovered · +$'+payout)}else toast('Storage full — sell ore at the surface.');state.depth=Math.min(6371,state.depth+18);makeCave();if(state.depth>=6371){state.depth=6371;ui('breakScreen').style.display='grid';state.core=true}}else if(state.depth>0&&Math.floor(state.depth/100)!==Math.floor((state.depth-meters)/100)){toast('Depth '+fmt(state.depth)+'m · '+l.name)}updateUI()}
function openLab(){if(state.mode==='cave'){toast('Return to the surface to access the lab.');return}let defs=[['power','Drill Power','Break tougher strata and increase each strike.'],['speed','Drill Speed','Shorten the time between mining strokes.'],['eff','Oil Efficiency','Reduce oil consumption per drill stroke.'],['store','Storage Capacity','Carry more ore before your next surface run.'],['heat','Heat Resistance','Protect drill systems in hot deep layers.']];let cost=k=>Math.floor([150,190,135,125,175][['power','speed','eff','store','heat'].indexOf(k)]*Math.pow(state.up[k]+1,1.62));ui('modal').innerHTML='<div class="modal-top"><div><div class="eyebrow">FIELD ENGINEERING / LAB 01</div><h2>Upgrade station</h2></div><button class="close">×</button></div><p class="modal-desc">Tune the rig for the next descent. Upgrades are permanent and stack with each level.<br>Available credits: <b style="color:#c8f36a">$'+fmt(state.money)+'</b></p><div class="upgrade-list">'+defs.map(([k,n,d])=>'<div class="upgrade"><div><div class="up-name">'+n+'</div><div class="up-note">'+d+'</div></div><div class="up-right"><div class="up-level">LEVEL '+state.up[k]+'</div><button class="buy" data-up="'+k+'">UPGRADE · $'+fmt(cost(k))+'</button></div></div>').join('')+'<div class="upgrade"><div><div class="up-name">Rig service</div><div class="up-note">Restore drill integrity to 100%.</div></div><div class="up-right"><div class="up-level">CONDITION '+fmt(state.dur)+'%</div><button class="buy" data-repair="1">REPAIR · $'+Math.floor((100-state.dur)*1.2)+'</button></div></div></div><div class="modal-footer"><span>TECHNICIAN ON DUTY</span><span>POWER GRID · NOMINAL</span></div>';ui('modalWrap').classList.add('open');ui('modal').querySelector('.close').onclick=closeModal;ui('modal').querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{let k=b.dataset.up,c=cost(k);if(state.money<c){toast('Not enough credits. Sell a few ore loads first.');return}state.money-=c;state.up[k]++;openLab();updateUI();toast('Upgrade installed · '+defs.find(d=>d[0]===k)[1])});ui('modal').querySelector('[data-repair]').onclick=()=>{let c=Math.floor((100-state.dur)*1.2);if(state.money<c){toast('Not enough credits for a full service.');return}state.money-=c;state.dur=100;openLab();updateUI();toast('Drill serviced and ready.')};}
function openShop(){if(state.mode==='cave'){toast('The depot is back at the surface.');return}let packs=[[25,55],[60,120],[130,230]];ui('modal').innerHTML='<div class="modal-top"><div><div class="eyebrow">FUEL & LUBRICANTS / DEPOT 02</div><h2>Oil supply</h2></div><button class="close">×</button></div><p class="modal-desc">Industrial lubricant keeps the deep-drive motor cool. Oil is consumed with every stroke below ground.</p><div class="oil-meter"><div class="oil-meter-top"><span>RESERVOIR</span><span>'+fmt(state.oil)+' / '+state.oilMax+' L</span></div><div class="meter"><i style="width:'+state.oil/state.oilMax*100+'%"></i></div></div><div class="oil-options">'+packs.map(([qty,cost])=>'<div class="oil-card"><strong>+'+qty+' L</strong><small>FIELD OIL · $'+cost+'</small><button class="buy" data-oil="'+qty+'" data-cost="'+cost+'">PURCHASE</button></div>').join('')+'</div><div class="modal-footer"><span>DEPOT TERMINAL · ONLINE</span><span>CREDITS $'+fmt(state.money)+'</span></div>';ui('modalWrap').classList.add('open');ui('modal').querySelector('.close').onclick=closeModal;ui('modal').querySelectorAll('[data-oil]').forEach(b=>b.onclick=()=>{let n=+b.dataset.oil,c=+b.dataset.cost;if(state.money<c){toast('Insufficient credits.');return}if(state.oil>=state.oilMax){toast('Tank is already full.');return}state.money-=c;state.oil=Math.min(state.oilMax,state.oil+n);updateUI();openShop();toast(n+' L added to reservoir.')})}
function closeModal(){ui('modalWrap').classList.remove('open')}ui('modalWrap').addEventListener('click',e=>{if(e.target===ui('modalWrap'))closeModal()});ui('labButton').onclick=openLab;ui('shopButton').onclick=openShop;ui('surfaceButton').onclick=()=>setMode(state.mode==='surface'?'cave':'surface');ui('continueBtn').onclick=()=>{ui('breakScreen').style.display='none';toast('The core lies behind you. Drill on.')};

