content.text:
.right-actions{position:absolute;right:28px;bottom:26px;display:flex;flex-direction:column;align-items:flex-end;gap:7px}
.action{pointer-events:auto;background:var(--panel);border:1px solid var(--line);padding:9px 13px;color:var(--ink);font:10px 'DM Mono';cursor:pointer;transition:.2s}
.action:hover{border-color:var(--lime);color:var(--lime)}
.action em{font-style:normal;color:var(--lime);margin-right:7px}
.modal-wrap{pointer-events:auto;position:absolute;inset:0;background:#05090894;display:none;align-items:center;justify-content:center;backdrop-filter:blur(5px)}
.modal-wrap.open{display:flex}
.modal{width:min(570px,calc(100vw - 32px));max-height:85vh;overflow:auto;background:#111a17;border:1px solid #c7ef6d4d;box-shadow:0 20px 80px #0009;padding:26px}
.modal-top{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:18px}
.modal h2{margin:7px 0 0;font-size:25px;letter-spacing:-.04em}
.modal-desc{font-size:12px;line-height:1.6;color:#9aa89e;margin:16px 0}
.oil-card button{margin-top:13px;width:100%}
.modal-footer{border-top:1px solid var(--line);padding-top:14px;margin-top:18px;display:flex;justify-content:space-between;color:#91a096;font:9px 'DM Mono'}
.break-card button{margin-top:13px;padding:12px 18px;border:0;background:var(--lime);color:#152017;font:11px 'DM Mono';cursor:pointer}
.right-actions{right:14px;bottom:14px}
.modal{padding:19px}

