const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{const b=await chromium.launch({headless:true,args:['--disable-gpu','--no-sandbox']});const p=await b.newPage({viewport:{width:1024,height:768}});p.setDefaultTimeout(4000);p.on('pageerror',e=>console.log('ERR',e.message));await p.goto('http://localhost:3002');await p.waitForTimeout(1000);console.log('pointer events',await p.locator('#surfaceButton').evaluate(e=>[getComputedStyle(e).pointerEvents,getComputedStyle(e.parentElement).pointerEvents]));await p.locator('#surfaceButton').click({force:true});await p.waitForTimeout(100);console.log('cave?',await p.locator('#layer').innerText());for(let i=0;i<7;i++){await p.locator('canvas').click({position:{x:512,y:380},force:true});await p.waitForTimeout(280)}console.log('mined',await p.locator('#depth').innerText(),'oil',await p.locator('#oil').innerText());await p.locator('#surfaceButton').click({force:true});await p.waitForTimeout(250);console.log('sold',await p.locator('#money').innerText(),await p.locator('#toast').innerText());await p.locator('#labButton').click({force:true});console.log('lab',await p.locator('#modal h2').innerText());await p.locator('[data-repair]').click({force:true});console.log('repair',await p.locator('#money').innerText());await p.locator('.close').click({force:true});await p.locator('#shopButton').click({force:true});console.log('shop',await p.locator('#modal h2').innerText());await p.locator('button[data-oil]').first().click({force:true});console.log('purchase',await p.locator('#oil').innerText(),await p.locator('#money').innerText());await p.screenshot({path:'screenshots/final-surface.jpg',type:'jpeg',quality:75,timeout:6000});await b.close()})().catch(e=>{console.error(e);process.exit(1)});
