(async()=>{let b=await chromium.launch({headless:true,args:['--disable-gpu','--no-sandbox']});let p=await b.newPage({viewport:{width:800,height:600}});p.setDefaultTimeout(2000);p.on('pageerror',e=>console.log('PAGE ERROR',e.message));await p.goto('http://localhost:3002');await p.waitForTimeout(600);let run=async s=>p.evaluate(s);console.log('before',await p.locator('#money').innerText());await run("document.querySelector('#surfaceButton').click()");await p.waitForTimeout(100);console.log('depth mode',await p.locator('#layer').innerText());for(let i=0;i<6;i++){await run("document.querySelector('canvas').dispatchEvent(new MouseEvent('click',{bubbles:true}))");await p.waitForTimeout(260)}console.log('mined',await p.locator('#depth').innerText(),await p.locator('#oil').innerText());await run("document.querySelector('#surfaceButton').click()");await p.waitForTimeout(200);console.log('sale',await p.locator('#money').innerText(),await p.locator('#toast').innerText());await run("document.querySelector('#labButton').click()");console.log('lab',await p.locator('#modal h2').innerText());await run("document.querySelector('[data-repair]').click()");await run("document.querySelector('.close').click()");await run("document.querySelector('#shopButton').click()");console.log('shop',await p.locator('#modal h2').innerText());await run("document.querySelector('[data-oil]').click()");console.log('oil purchase',await p.locator('#oil').innerText());await p.screenshot({path:'screenshots/final-surface.jpg',type:'jpeg',quality:70,timeout:5000});await b.close()})().catch(e=>{console.log('ERROR',e.message);process.exit(1)});
